'use strict';

// MODULES //

var tape = require( 'tape' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var randu = require( '@stdlib/random/base/randu' );
var fresnelf = require( './../lib/main.js' );


// FIXTURES //

var smallPositive = require( './fixtures/c/cephes/small.json' );
var mediumPositive = require( './fixtures/c/cephes/medium.json' );
var largePositive = require( './fixtures/c/cephes/large.json' );
var hugePositive = require( './fixtures/c/cephes/huge.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof fresnelf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `[0.0, 0.0]` if provided `0.0`', function test( t ) {
	var v = fresnelf( 0.0 );
	t.strictEqual( v[0], 0.0, 'returns expected value' );
	t.strictEqual( v[1], 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function computes Fresnel integrals (small positive values)', function test( t ) {
	var expectedS;
	var expectedC;
	var C;
	var S;
	var x;
	var y;
	var i;

	x = smallPositive.x;
	S = smallPositive.S;
	C = smallPositive.C;

	for ( i = 0; i < x.length; i++ ) {
		y = fresnelf( x[i] );
		expectedS = f32( S[i] );
		expectedC = f32( C[i] );
		t.strictEqual( isAlmostSameValuef( y[0], expectedS, 2 ), true, 'returns expected value' );
		t.strictEqual( isAlmostSameValuef( y[1], expectedC, 5 ), true, 'returns expected value' );
	}
	t.end();
});

