tape( 'the function is an odd function of x', function test( t ) {
	var yn;
	var yp;
	var x;
	var i;

	for ( i = 0; i < 500; i++ ) {
		x = f32( randu() * 36.0 );
		yn = fresnelf( -x );
		yp = fresnelf( x );

		t.strictEqual( yp[0], -yn[0], 'returns expected value' );
		t.strictEqual( yp[1], -yn[1], 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `[0.5, 0.5]` if provided `+infinity`', function test( t ) {
	var v = fresnelf( PINF );
	t.strictEqual( v[0], 0.5, 'returns expected value' );
	t.strictEqual( v[1], 0.5, 'returns expected value' );
	t.end();
});

tape( 'the function returns `[-0.5, -0.5]` if provided `-infinity`', function test( t ) {
	var v = fresnelf( NINF );
	t.strictEqual( v[0], -0.5, 'returns expected value' );
	t.strictEqual( v[1], -0.5, 'returns expected value' );
	t.end();
});

tape( 'the function returns `[NaN, NaN]` if provided a `NaN`', function test( t ) {
	var v = fresnelf( NaN );
	t.strictEqual( isnanf( v[0] ), true, 'returns expected value' );
	t.strictEqual( isnanf( v[1] ), true, 'returns expected value' );
	t.end();
});
